function dijkstra(graph, source) {
  const dist = new Map();
  const parent = new Map();
  for (const node of graph.nodes) dist.set(node, Infinity);
  dist.set(source, 0);

  const heap = new MinHeap();       // ordered by distance
  heap.push([0, source]);

  while (!heap.isEmpty()) {
    const [d, u] = heap.pop();
    if (d > dist.get(u)) continue;  // a stale entry, already improved on

    for (const { to, weight } of graph.neighbors(u)) {
      const candidate = dist.get(u) + weight;
      if (candidate < dist.get(to)) {
        dist.set(to, candidate);
        parent.set(to, u);
        heap.push([candidate, to]);
      }
    }
  }

  return { dist, parent };
}

