import heapq

def dijkstra(graph, source):
    dist = {node: float("inf") for node in graph.nodes}
    dist[source] = 0
    parent = {}

    heap = [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue                 # a stale entry, already improved on

        for to, weight in graph.neighbors(u):
            candidate = dist[u] + weight
            if candidate < dist[to]:
                dist[to] = candidate
                parent[to] = u
                heapq.heappush(heap, (candidate, to))

    return dist, parent

vector<long long> dijkstra(const vector<vector<pair<int,int>>>& adj, int source) {
    const long long INF = LLONG_MAX / 4;
    vector<long long> dist(adj.size(), INF);
    dist[source] = 0;

    priority_queue<pair<long long,int>,
                   vector<pair<long long,int>>,
                   greater<>> heap;
    heap.push({0, source});

    while (!heap.empty()) {
        auto [d, u] = heap.top();
        heap.pop();
        if (d > dist[u]) continue;   // a stale entry, already improved on

        for (auto [to, weight] : adj[u]) {
            long long candidate = dist[u] + weight;
            if (candidate < dist[to]) {
                dist[to] = candidate;
                heap.push({candidate, to});
            }
        }
    }
    return dist;
}
